import{R as t}from"./chunks/RecommendationPageIntro.BmaEjxld.js";import{c as a,o as n,j as i,J as r,af as o,a as s}from"./chunks/framework.gyjl__eE.js";import"./chunks/recommendations.B4rZ4dra.js";const k=JSON.parse('{"title":"Storywriting","description":"","frontmatter":{"title":"Storywriting"},"headers":[],"relativePath":"recommendations/storywriting/index.md","filePath":"recommendations/storywriting/index.md"}'),l={name:"recommendations/storywriting/index.md"},m=Object.assign(l,{setup(h){return(p,e)=>(n(),a("div",null,[e[0]||(e[0]=i("h1",{id:"storywriting-creative-writing",tabindex:"-1"},[s("Storywriting & Creative Writing "),i("a",{class:"header-anchor",href:"#storywriting-creative-writing","aria-label":"Permalink to “Storywriting & Creative Writing”"},"​")],-1)),e[1]||(e[1]=i("p",null,[i("strong",null,"Narrative-tuned models"),s(" optimized for immersive storytelling, rich character arcs, evocative prose, and genre-aware stylistic control. These models excel at crafting original fiction, expanding existing worlds, generating dialogue with emotional nuance, and maintaining long-range plot coherence-even across tens of thousands of tokens.")],-1)),r(t,{usageKey:"storywriting"}),e[2]||(e[2]=o(`<h1 id="prompting" tabindex="-1">Prompting <a class="header-anchor" href="#prompting" aria-label="Permalink to “Prompting”">​</a></h1><p>Creative writing models respond best when you specify the story constraints without over-constraining the prose itself. Strong prompts define the premise, voice, stakes, and scene goals.</p><ol><li><strong>Establish the creative frame.</strong> State the genre, point of view, tone, and any worldbuilding rules that matter.</li><li><strong>Define the scene objective.</strong> Explain what must happen emotionally or plot-wise in the passage.</li><li><strong>Use stylistic constraints carefully.</strong> Ask for concrete qualities like pacing, sensory detail, or dialogue density instead of vague requests like &quot;make it better.&quot;</li></ol><p>Below are examples of well-structured prompts, followed by examples of what to avoid.</p><h2 id="effective-examples" tabindex="-1">Effective Examples <a class="header-anchor" href="#effective-examples" aria-label="Permalink to “Effective Examples”">​</a></h2><h3 id="writing-a-focused-scene" tabindex="-1">Writing a Focused Scene <a class="header-anchor" href="#writing-a-focused-scene" aria-label="Permalink to “Writing a Focused Scene”">​</a></h3><p>This prompt sets a clear premise and emotional target.</p><div class="language-md"><button title="Copy Code" class="copy"></button><span class="lang">md</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Write a 900-1200 word fantasy scene in third-person limited from Mara&#39;s point of view.</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Story context:</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">\`\`\`txt</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Mara is a novice archivist who has secretly used forbidden magic to restore damaged manuscripts.</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Tonight she discovers that one of the restored books has begun rewriting itself with details from her own future.</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">\`\`\`</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Scene requirements:</span></span>
<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> The scene takes place alone in the archive after midnight.</span></span>
<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> The tone should be tense and intimate, not action-heavy.</span></span>
<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> Include at least one moment where Mara is tempted to keep reading and one moment where she considers burning the book.</span></span>
<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> End with a reveal that someone else has already annotated the future text.</span></span></code></pre></div><p><strong>Why this works:</strong></p><ul><li><strong>Provides narrative scaffolding:</strong> The model knows the character, setting, and core conflict.</li><li><strong>Targets the emotional shape:</strong> &quot;tense and intimate&quot; is more actionable than a generic quality label.</li><li><strong>Defines the ending beat:</strong> The reveal gives the scene a destination.</li></ul><h3 id="revising-for-style" tabindex="-1">Revising for Style <a class="header-anchor" href="#revising-for-style" aria-label="Permalink to “Revising for Style”">​</a></h3><p>This prompt provides source text and a specific revision goal.</p><div class="language-md"><button title="Copy Code" class="copy"></button><span class="lang">md</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Revise the paragraph below to feel more lyrical and atmospheric while preserving the original events and meaning. Keep it to one paragraph.</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Original:</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">\`\`\`txt</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Jon walked into the abandoned train station. It was quiet and cold. He saw a suitcase on a bench and heard water dripping somewhere in the dark.</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">\`\`\`</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Constraints:</span></span>
<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> Do not change the point of view.</span></span>
<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> Do not add new plot events.</span></span>
<span class="line"><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> Emphasize sound and texture.</span></span></code></pre></div><p><strong>Why this works:</strong></p><ul><li><strong>Supplies the text to transform:</strong> The model can revise instead of inventing from scratch.</li><li><strong>Preserves intent:</strong> The constraints guard against plot drift.</li><li><strong>Names the craft target:</strong> &quot;sound and texture&quot; is concrete and useful.</li></ul><h2 id="poor-examples-what-to-avoid" tabindex="-1">Poor Examples (What to Avoid) <a class="header-anchor" href="#poor-examples-what-to-avoid" aria-label="Permalink to “Poor Examples (What to Avoid)”">​</a></h2><p>The following prompts are less effective because they are too vague, too contradictory, or too dependent on the model guessing your taste.</p><h3 id="generic-story-request" tabindex="-1">Generic Story Request <a class="header-anchor" href="#generic-story-request" aria-label="Permalink to “Generic Story Request”">​</a></h3><p>This prompt does not give the model enough creative direction.</p><div class="language-md"><button title="Copy Code" class="copy"></button><span class="lang">md</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Write a fantasy story.</span></span></code></pre></div><p><strong>Why it&#39;s ineffective:</strong></p><ul><li><strong>No premise:</strong> The model has to invent the setting, conflict, and characters from nothing.</li><li><strong>No scale:</strong> It is unclear whether the user wants a paragraph, scene, outline, or full story.</li><li><strong>No stylistic direction:</strong> The result will usually be generic fantasy prose.</li></ul><h3 id="contradictory-revision-prompt" tabindex="-1">Contradictory Revision Prompt <a class="header-anchor" href="#contradictory-revision-prompt" aria-label="Permalink to “Contradictory Revision Prompt”">​</a></h3><p>This prompt asks for incompatible outcomes at the same time.</p><div class="language-md"><button title="Copy Code" class="copy"></button><span class="lang">md</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Rewrite this to be more subtle, more dramatic, shorter, more detailed, and completely different.</span></span></code></pre></div><p><strong>Why it&#39;s ineffective:</strong></p><ul><li><strong>Conflicting goals:</strong> &quot;shorter&quot; and &quot;more detailed&quot; pull in opposite directions.</li><li><strong>No priority order:</strong> The model cannot tell which requirement matters most.</li><li><strong>Undefined revision scope:</strong> &quot;completely different&quot; conflicts with the idea of a rewrite.</li></ul>`,27))]))}});export{k as __pageData,m as default};
